class Solution:
    def expressiveWords(self, s: str, words: list[str]) -> int:
        def get_groups(w):
            groups = []
            i = 0
            while i < len(w):
                j = i
                while j < len(w) and w[j] == w[i]:
                    j += 1
                groups.append((w[i], j - i))
                i = j
            return groups

        def stretchy(word):
            g1 = get_groups(s)
            g2 = get_groups(word)
            if len(g1) != len(g2):
                return False
            for (c1, n1), (c2, n2) in zip(g1, g2):
                if c1 != c2:
                    return False
                if n1 < n2:
                    return False
                if n1 != n2 and n1 < 3:
                    return False
            return True

        return sum(stretchy(w) for w in words)

